            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "It is the possibility of happiness, intelligence and power that give life its sanctity, and they are absent in the case of a poor, misshapen, paralyzed, unthinking creature.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "When one door of happiness closes, another opens; but often we look so long at the closed door that we do not see the one which has been opened for us.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Believe, when you are most unhappy, that there is something for you to do in the world. So long as you can sweeten another's pain, life is not in vain.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "No doubt the reason is that character cannot be developed in ease and quiet. Only through experience of trial and suffering can the soul be strengthened, vision cleared, ambition inspired, and success achieved.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Avoiding danger is no safer in the long run than outright exposure. The fearful are caught as often as the bold.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Security is mostly a superstition. It does not exist in nature, nor do the children of men as a whole experience it. Avoiding danger is no safer in the long run than outright exposure. Life is either a daring adventure, or nothing.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "I do not want the peace that passeth understanding. I want the understanding which bringeth peace.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Some people do not like to think. If one thinks, one must reach conclusions; and conclusions are not always pleasant. They are a thorn in the spirit. But I consider it a priceless gift and a deep responsibility to think.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Alone we can do so little; together we can do so much.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Tyranny cannot defeat the power of ideas.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "The most important day I remember in all my life is the one on which my teacher, Anne Mansfield Sullivan, came to me.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "I remember the morning that I first asked the meaning of the word, \"love.\"", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Is love the sweetness of flowers?", Author = "Helen Keller" },
