            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "In a flash I knew that the word was the name of the process that was going on in my head. This was my first conscious perception of an abstract idea.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "The beautiful truth burst upon my mind - I felt that there were invisible lines stretched between my spirit and the spirits of others.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Now, so far as I can judge, self-love is the root of all evil.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Love like Ruth's, love which can rise above conflicting creeds and deep-seated racial prejudices, is hard to find in all the world.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "The Bible gives me a deep, comforting sense that \"things seen are temporal and things unseen are eternal.\"", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "I do not remember a time since I have been capable of loving books that I have not loved Shakespeare.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "There are moments when I feel that the Shylocks, the Judases, and even the Devil, are broken spokes in the great wheel of good which shall in due time be made whole.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "If it is true that the violin is the most perfect of musical instruments, then Greek is the violin of human thought.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Toleration is the greatest gift of the mind; it requires the same effort of the brain that it takes to balance oneself on a bicycle.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "It is wonderful how much time good people spend fighting the devil. If they would only expend the same amount of energy loving their fellow men, the devil would die in his own tracks of ennui.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "No matter how dull, or how mean, or how wise a man is, he feels that happiness is his indisputable right.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "I have found out that though the ways in which I can make myself useful are few, yet the work open to me is endless.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "The good is the only world, and that world is a world of spirit. It is also a universe where order is All, where an unbroken logic holds the parts together, where disorder defines itself as non-existence, where evil, as St. Augustine held, is delusion, and therefore is not.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "To know the history of philosophy is to know that the highest thinkers of the ages, the seers of the tribes and the nations, have been optimists. The growth of philosophy is the story of man's spiritual life.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Tolerance is the first principle of community; it is the spirit which conserves the best that all men think.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "The idea of brotherhood redawns upon the world with a broader significance than the narrow association of members in a sect or creed.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "The test of all beliefs is their practical effect in life. If it be true that optimism compels the world forward, and pessimism retards it, then it is dangerous to propagate a pessimistic philosophy.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "If I regarded my life from the point of view of the pessimist, I should be undone. I should seek in vain for the light that does not visit my eyes and the music that does not ring in my ears.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Every optimist moves along with progress and hastens it, while every pessimist would keep the world at a standstill. The consequence of pessimism in the life of a nation is the same as in the life of the individual.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Optimism is the faith that leads to achievement; nothing can be done without hope.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Optimism is the harmony between man's spirit and the spirit of God pronouncing His works good.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "I who cannot see find hundreds of things to interest me through mere touch.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "I feel the delightful, velvety texture of a flower, and discover its remarkable convolutions; and something of the miracle of Nature is revealed to me.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Use your eyes as if tomorrow you would be stricken blind.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Hear the music of voices, the song of a bird, the mighty strains of an orchestra, as if you would be stricken deaf to-morrow.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Touch each object you want to touch as if tomorrow your tactile sense would fail.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Smell the perfume of flowers, taste with relish each morsel, as if tomorrow you could never smell and taste again.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "Make the most of every sense; glory in all the facets of pleasure and beauty which the world reveals to you through the several means of contact which Nature provides.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "A happy life consists not in the absence, but in the mastery of hardships.", Author = "Helen Keller" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Helen_Keller", Text = "It all comes to this: the simplest way to be happy is to do good.", Author = "Helen Keller" },
